do $$ begin if not exists (select 1 from pg_enum where enumtypid = (select oid from pg_type where typname = 'app_permission' and typnamespace = (select oid from pg_namespace where nspname = 'rbac')) and enumlabel = 'prayer.read') then alter type rbac.app_permission add value 'prayer.read'; alter type rbac.app_permission add value 'prayer.create'; alter type rbac.app_permission add value 'prayer.delete'; alter type rbac.app_permission add value 'preferences.update'; alter type rbac.app_permission add value 'planetary.read'; alter type rbac.app_permission add value 'planetary.create'; alter type rbac.app_permission add value 'planetary.delete'; end if; end$$;
